static void ui_enter_deep_sleep(void)
{
    const gpio_num_t wake_gpios[] = {DEEP_SLEEP_WAKE_GPIO};
    const uint64_t wake_mask = DEEP_SLEEP_WAKE_MASK;

    ui_buzzer_set(false);
    ui_buzzer_set_warning_alarm(false);
    gpio_set_level(HV_ENABLE_GPIO, 0);

    for (size_t i = 0; i < (sizeof(wake_gpios) / sizeof(wake_gpios[0])); i++)
    {
        gpio_num_t gpio_num = wake_gpios[i];
        gpio_set_direction(gpio_num, GPIO_MODE_INPUT);
        gpio_pullup_en(gpio_num);
        gpio_pulldown_dis(gpio_num);
        gpio_sleep_set_direction(gpio_num, GPIO_MODE_INPUT);
        gpio_sleep_set_pull_mode(gpio_num, GPIO_PULLUP_ONLY);
    }

    esp_err_t wake_ret = esp_deep_sleep_enable_gpio_wakeup(wake_mask, ESP_GPIO_WAKEUP_GPIO_LOW);
    if (wake_ret != ESP_OK)
    {
        ESP_LOGE(UI_EVT_TAG, "deep sleep wake config failed: %s", esp_err_to_name(wake_ret));
        return;
    }

    ESP_LOGI(UI_EVT_TAG, "Entering deep sleep, wake GPIO%d low only", DEEP_SLEEP_WAKE_GPIO);
    vTaskDelay(pdMS_TO_TICKS(20));
    esp_deep_sleep_start();
}

